using System.ComponentModel;
using System.Globalization;

namespace Pulsar.Domain.Common;

// Strongly typed identifiers: a role id can never be passed where a user id is expected.
// Values are UUIDv7 generated by the application (ADR-0004).

/// <summary>
/// User identifier. It is also the ASP.NET Core Identity key, and Identity converts keys from strings (cookie claims)
/// through the type's <see cref="TypeConverter"/>.
/// </summary>
[TypeConverter(typeof(UserIdTypeConverter))]
public readonly record struct UserId(Guid Value)
{
    public static UserId New() => new(Guid.CreateVersion7());

    public override string ToString() => Value.ToString();
}

public readonly record struct RoleId(Guid Value)
{
    public static RoleId New() => new(Guid.CreateVersion7());

    public override string ToString() => Value.ToString();
}

public readonly record struct NodeId(Guid Value)
{
    public static NodeId New() => new(Guid.CreateVersion7());

    public override string ToString() => Value.ToString();
}

public readonly record struct ServerId(Guid Value)
{
    public static ServerId New() => new(Guid.CreateVersion7());

    public override string ToString() => Value.ToString();
}

public readonly record struct TemplateId(Guid Value)
{
    public static TemplateId New() => new(Guid.CreateVersion7());

    public override string ToString() => Value.ToString();
}

public readonly record struct OperationId(Guid Value)
{
    public static OperationId New() => new(Guid.CreateVersion7());

    public override string ToString() => Value.ToString();
}

/// <summary>Converts <see cref="UserId"/> to and from its GUID string form.</summary>
public sealed class UserIdTypeConverter : TypeConverter
{
    public override bool CanConvertFrom(ITypeDescriptorContext? context, Type sourceType) =>
        sourceType == typeof(string) || base.CanConvertFrom(context, sourceType);

    public override bool CanConvertTo(ITypeDescriptorContext? context, Type? destinationType) =>
        destinationType == typeof(string) || base.CanConvertTo(context, destinationType);

    public override object? ConvertFrom(ITypeDescriptorContext? context, CultureInfo? culture, object value) =>
        value is string text ? new UserId(Guid.Parse(text, CultureInfo.InvariantCulture)) : base.ConvertFrom(context, culture, value);

    public override object? ConvertTo(ITypeDescriptorContext? context, CultureInfo? culture, object? value, Type destinationType) =>
        destinationType == typeof(string) && value is UserId id
            ? id.Value.ToString()
            : base.ConvertTo(context, culture, value, destinationType);
}
